// Local approval prototype. All observations, materials and state transitions are fictitious.
// No network calls, device actions, model requests, persistence or publishing.
const hp = value => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
function tr(cells,cls=''){return `<tr class="${cls}">${cells.map(x=>`<td>${x}</td>`).join('')}</tr>`;}
const aiPlatforms = ['DeepSeek','千问','Kimi','豆包','腾讯元宝'];
const sceneNames = ['全部场景','实施适配','功能比较','价格与成本'];
const query = new URLSearchParams(location.search);
const growth = {
  mode:'ready', own:'云衡', compare:query.get('compare') || '锐川', platform:query.get('platform') || '全部平台',
  scenario:query.get('scene') || '全部场景', revision:6, scopeReviewed:false, identityConfirmed:false,
  sourceTab:'observed', capture:'idle', opportunity:'case', policy:'neutral', policyVersion:1,
  actionRevision:1, actionApproved:false, stale:false, revisions:[], owner:'内容团队',
  delivery:'not_started', draft:'none', channel:'website', published:false, observation:'idle', conditions:false,
  assets:[{id:'spec',title:'云衡产品规格页',type:'产品规格',status:'fact_approved',url:'https://yunheng.example.com/specs',text:'云衡提供门店、区域与总部三类权限，可按角色配置查看范围。',version:2},
    {id:'case',title:'连锁门店实施案例资料',type:'客户案例',status:'captured',url:'内部文字资料（虚构）',text:'云衡项目在三个门店完成分级权限部署；试点范围、客户授权和持续运行数据仍需核实。',version:1}]
};
const opportunities = [
  {id:'case',scene:'实施适配',platform:'DeepSeek',title:'补齐连锁门店的权限边界与实施证据',tag:'内容与证据供给',material:'案例尚未核实，先完成素材准备',asset:'产品页 / 权限与实施章节',task:'补一张角色权限表及一个经客户授权的实施案例，明确试点范围和适用限制。',fact:'竞品回答明确提到跨门店权限和实施案例，我方在该条回答中未被推荐。',hypothesis:'缺少可核实的公开材料可能是值得验证的方向，不代表已证明未被推荐的原因。',evidence:'“锐川适用于多门店协同，其实施案例列明总部和门店的管理边界。”'},
  {id:'fact',scene:'功能比较',platform:'千问',title:'核对历史文章的权限描述，更新产品规格说明',tag:'品牌认知',material:'规格事实已批准，可准备内容方案',asset:'产品规格页 / 角色与权限',task:'明确三类角色的适用范围，保留规格版本和事实出处，向旧文章维护方提交准确资料。',fact:'本次回答沿用旧文章中的“只支持单门店管理”描述，与我方已批准规格事实不一致。',hypothesis:'需要分别核查文章版本与平台回答，纠错提交不保证回答立即更新。',evidence:'“云衡主要用于单门店管理，多区域权限需要额外核对。”'},
  {id:'cost',scene:'价格与成本',platform:'Kimi',title:'把报价边界整理成可核对的配置说明',tag:'场景覆盖',material:'需要产品与商务确认计费边界',asset:'选型 FAQ / 配置与价格边界',task:'说明设备数量、服务范围与实施费用的计费条件；没有批准价格时不写具体金额。',fact:'该条回答按配置与总体成本比较方案，我方资料未提供可直接核对的计费范围。',hypothesis:'当前仅能确认资料缺口，不能推断我方价格竞争力或实际报价。',evidence:'“建议根据门店数量、部署范围和服务内容核对总体预算。”'}
];
if(!['锐川','拓域','朗测','瀚策'].includes(growth.compare))growth.compare='锐川';
if(!['全部平台',...aiPlatforms].includes(growth.platform))growth.platform='全部平台';
if(!sceneNames.includes(growth.scenario))growth.scenario='全部场景';
const assetsReady = () => growth.opportunity === 'fact' || (growth.opportunity === 'case' && growth.assets.find(a=>a.id==='case')?.status === 'fact_approved');
const chosen = () => opportunities.find(o=>o.id===growth.opportunity) || opportunities[0];
const matchingTaskScope = () => growth.compare==='锐川' && (growth.platform==='全部平台'||growth.platform===chosen().platform) && (growth.scenario==='全部场景'||growth.scenario===chosen().scene);
function taskScopeNotice(){const o=chosen();return screen('CONTEXT','当前范围尚无这条行动的对应证据','切换范围不会把已有原文改写成另一个品牌或平台的证据。',`<section class="panel pad"><h2>当前选择：${hp(growth.compare)} · ${hp(growth.platform)} · ${hp(growth.scenario)}</h2><p>示例行动 ACT-01 的原始范围是：云衡 / 锐川 · ${o.platform} · ${o.scene}。该行动及历史产物保留。</p><p class="sub">可以继续查看当前品牌对照，或明确返回行动原范围。原型没有为当前范围准备可核实的竞争机会。</p><div class="page-actions">${actionButton('查看当前品牌对照',"showView('brands')")}${actionButton('返回行动原范围',`selectOpportunity('${o.id}',state.view)`,'primary')}</div></section>`);}
const chip = p => `<span class="platform-chip"><i>${hp(({DeepSeek:'D','千问':'千',Kimi:'K','豆包':'豆','腾讯元宝':'元'})[p] || 'AI')}</i>${hp(p)}</span>`;
const actionButton = (text,js,tone='') => `<button class="btn ${tone}" onclick="${js}">${text}</button>`;
const note = (text,tone='') => `<div class="notice ${tone}">${icon('info')}<div>${text}</div></div>`;
const v3Scores = (brand,platform=growth.platform) => {
  const all = {'云衡':[60,50,40,60],'锐川':[80,75,70,85],'拓域':[65,60,50,75],'朗测':[35,25,null,40],'瀚策':[0,0,0,0]};
  let values = [...(all[brand] || all['云衡'])];
  if(brand==='朗测'&&!growth.identityConfirmed)return [null,null,null,null];
  if(platform!=='全部平台'){
    if(brand==='云衡')values=[...({DeepSeek:[60,50,40,60],'千问':[80,60,50,60],Kimi:[50,50,35,50],'豆包':[50,40,null,50],'腾讯元宝':[45,40,30,45]})[platform]];
    else {const adjustment=aiPlatforms.indexOf(platform)*5;values=values.map(v=>v===null?null:Math.max(0,v-adjustment));}
  }
  if(growth.mode!=='ready') values[2]=null;
  if(growth.mode==='failed') return [null,null,null,null];
  return values;
};
const total = values => values.some(n=>n===null) ? '—' : Math.round(values.reduce((n,v,i)=>n+v*[.3,.3,.2,.2][i],0));
const num = value => value===null ? '—' : value;
const answerCount = brand => {const value=v3Scores(brand)[0],n=growth.platform==='全部平台'?100:20;return value===null?'尚未完成分析':`${Math.round(value*n/100)} / ${n}`;};
function preview(){return `<div class="preview"><span class="sub">原型状态预览 · 仅本地示意，不触发真实任务</span>${[['ready','结果可用'],['pending','问题待审核'],['failed','分析失败']].map(([v,l])=>actionButton(l,`growth.mode='${v}';showView(state.view)`,growth.mode===v?'active':'')).join('')}</div>`;}
function scope(){return `<section class="panel context-strip" aria-label="统一比较范围"><label>自有品牌<select class="select" aria-label="自有品牌"><option>云衡</option></select></label><label>对比品牌<select class="select" aria-label="对比品牌" onchange="setScope('compare',this.value)">${['锐川','拓域','朗测','瀚策'].map(b=>`<option ${growth.compare===b?'selected':''}>${b}</option>`).join('')}</select></label><label>目标平台<select class="select" aria-label="目标平台" onchange="setScope('platform',this.value)">${['全部平台',...aiPlatforms].map(p=>`<option ${growth.platform===p?'selected':''}>${p}</option>`).join('')}</select></label><label>需求场景<select class="select" aria-label="需求场景" onchange="setScope('scenario',this.value)">${sceneNames.map(s=>`<option ${growth.scenario===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="scope-line">审计 A-1024 · 修订 ${growth.revision} · 每题每平台一次 · 固定规则 v1${growth.scopeReviewed?' · 问题范围已确认':''}</div></section>`;}
function setScope(key,value){growth[key]=value;showView(state.view);}
function screen(eyebrow,title,sub,body,buttons=''){return head(eyebrow,title,sub,buttons)+preview()+scope()+body;}
function readiness(){
  const pending=growth.mode==='pending', failed=growth.mode==='failed';
  const rows=[['回答采集',failed?'4 / 5 · 1 项失败':'100 / 100 · 已取得','失败和不完整回答不按品牌缺席处理','采集详情',"showView('capture')"],['语义分析',failed?'0 / 184 片段':'保存文字已分析','回答和文章分析覆盖分别核对','查看分析状态',"statusDetails()"],['品牌身份',growth.identityConfirmed?'观察主体已确认':'1 个主体待核实','未登记品牌可以独立确认用于比较','核实品牌',"identityDrawer('朗测')"],['问题资格',pending?'2 个待审核':'16 项纳入 · 4 项排除','品牌预设型问题与中性选型分开','审核问题范围',"promptReview()"],['来源正文','32 篇已保存 / 41 篇','正文完整性仍有未知，不封锁独立成立的回答结论','核对来源',"showView('sources')"],['四维评价',failed?'尚未分析':pending?'问题范围待确认':'本次评价可用','无显式排序的回答仍保留分项与证据','查看评分依据',"scoreExplanation()"],['可执行机会',failed?'暂不推导':assetsReady()?'材料可用，等待审核':'先准备真实材料','竞品证据不直接成为我方产品事实','查看具体任务',"showView('actions')"]];
  return `<section class="panel pad"><div class="sectionhead"><div><h2>本次结果可以判断什么？</h2><span class="sub">采集、分析、身份、问题与来源分别核对</span></div>${actionButton('查看全部前置条件','statusDetails()')}</div><div class="readiness">${rows.map(([t,v,d,l,js])=>`<div class="ready-item"><span class="sub">${t}</span><b>${v}</b><p>${d}</p><button class="textbtn" onclick="${js}">${l} →</button></div>`).join('')}</div></section>`;
}
function statusDetails(){openDrawer('本次结果的就绪条件',`<p>未知原因按对象列出，补齐条件后提示新的分析修订；旧报告不被静默改写。</p><div class="observation"><b>问题范围</b><p>2 条示例问题需要判断是否属于可比较的中性选型；未确认前暂停相应范围总分。</p></div><div class="observation"><b>来源完整性未知</b><p>已保存文字可以提供已观察到的正面证据，但未命中不能证明整篇文章未提及品牌。</p></div>${growth.mode==='failed'?'<div class="observation"><b>语义分析失败</b><p>184 个片段尚未成功分析。此时“实体 0”不表示没有品牌，不能推导我方缺席。</p></div>':''}`,actionButton('处理问题范围',"closeModal();promptReview()",'primary'));}
function promptReview(){modal('确认本次竞争评价的问题范围',`<p>保留原问题和分类依据；审核只决定评价范围，不发起重复采集。</p>${['连锁门店如何选择监测方案？','预算有限时，应比较哪些实施成本？'].map((q,i)=>`<div class="field"><label for="eligibility-${i}">${q}</label><select class="select" id="eligibility-${i}" aria-label="第${i+1}条问题资格"><option>纳入中性竞争评价</option><option>排除：问题预设品牌</option><option>暂不确定</option></select></div>`).join('')}<div class="field"><label for="scope-reason">审核依据</label><textarea id="scope-reason" placeholder="说明纳入或排除的理由"></textarea></div><p class="input-error" id="form-error" role="alert" hidden></p>`,actionButton('保存范围审核','saveScope()','primary'));}
function saveScope(){if(!document.getElementById('scope-reason').value.trim()){formError('请填写审核依据。');return;}growth.scopeReviewed=true;closeModal();modal('新的分析修订已就绪',`<p>示例：范围审核已保存，修订 ${growth.revision+1} 已就绪。当前旧修订保留。</p><p class="sub">真实系统需要等待分析任务完成，不会由页面直接计算分数。</p>`,actionButton('进入新修订',"growth.revision++;growth.mode='ready';closeModal();showView(state.view)",'primary'));}
function formError(text){const el=document.getElementById('form-error');el.hidden=false;el.textContent=text;}
function scoreExplanation(){modal('固定评价规则与原始依据',`<p>品牌出现 30% · 推荐强度 30% · 推荐位置 20% · 选择理由 20%。</p><p>无明确完整排序时位置保留未知，不按出现顺序编造名次，也不重新分配权重。</p><div class="quote">示例：“锐川适用于多门店协同，其实施案例列明总部和门店的管理边界。”</div><p>该片段支持具体理由观察，不证明文章导致了平台推荐。没有完整总分，仍可查看已具备证据的单维机会。</p>`,actionButton('核对回答与来源',"closeModal();showView('evidence')",'primary'));}
function opportunityCards(){
  let list=opportunities.filter(o=>growth.compare==='锐川'&&(growth.scenario==='全部场景'||o.scene===growth.scenario)&&(growth.platform==='全部平台'||o.platform===growth.platform));
  if(growth.policy==='cost')list=[...list].sort((a,b)=>(b.id==='cost')-(a.id==='cost'));
  if(growth.mode==='failed')return `<div class="blank-result"><h3>分析尚未成功，暂不推导竞争机会</h3><p>已保存回答与来源可查看；修复分析后生成新修订。</p>${actionButton('查看分析条件','statusDetails()')}</div>`;
  return list.map((o,i)=>`<article class="opportunity"><div class="sectionhead"><span class="ranklabel">0${i+1} / ${o.tag}</span>${chip(o.platform)}</div><h3>${o.title}</h3><p><span class="factflag">本次观察</span><br>${o.fact}</p><div class="material-state">我方材料：${o.material}</div><div class="meta-line"><span>场景：${o.scene}</span><span>交付：${o.asset}</span><span>建议负责人：${o.id==='cost'?'产品与商务':'内容团队'}</span></div><div class="actionfoot"><span class="sub">证据与材料就绪程度已列出 · 不承诺推荐提升</span><div class="buttons">${actionButton('查看证据与假设',`opportunityDrawer('${o.id}')`)}${actionButton('形成具体任务',`selectOpportunity('${o.id}','actions')`,'primary')}</div></div></article>`).join('') || '<div class="blank-result">该范围没有已具备依据的机会；不会为填满页面制造建议。</div>';
}
function focusOpportunity(id){if(growth.opportunity!==id){growth.opportunity=id;growth.actionApproved=false;growth.stale=false;growth.actionRevision=1;growth.revisions=[];growth.delivery='not_started';growth.draft='none';growth.published=false;growth.observation='idle';}}
function selectOpportunity(id,view){focusOpportunity(id);const o=chosen();growth.compare='锐川';growth.platform=o.platform;growth.scenario=o.scene;showView(view);}
function opportunityDrawer(id){focusOpportunity(id);const o=chosen();openDrawer(o.title,`<div class="scope-line">${chip(o.platform)}${badge(o.scene)}${badge('原因待验证','amber')}</div><h3>1. 观察事实</h3><p>${o.fact}</p><div class="quote">${o.evidence}</div><h3>2. 诊断假设与限制</h3><div class="assumption">${o.hypothesis}</div><h3>3. 我方需要处理的内容</h3><p><b>${o.asset}</b></p><p>${o.task}</p><div class="material-state">${o.material}</div><h3>4. 验收与后续观察</h3><p>事实、范围与证明材料一致；下一次沿用同一问题和平台，核对出现、推荐及对应理由。材料不齐先做核实任务。</p>`,actionButton('查看原文',"closeModal();showView('evidence')")+actionButton('进入对应行动',"closeModal();showView('actions')",'primary'));}
function overviewV3(){const scores=v3Scores(growth.own);return screen('AUDIT INSIGHT','从本次表现，找到值得执行的改进','先确认结果依据，再决定改哪一项内容。每条任务保留平台、问题和原文。',`<section class="panel pad result-summary"><div>${badge(growth.mode==='ready'?'本次样本结论':'结果尚有前置条件',growth.mode==='ready'?'teal':'amber')}<h2>${growth.mode==='failed'?'原始材料已保存，分析结果尚未可用':growth.mode==='pending'?'部分问题范围待确认，先保留已知观察':'云衡已被提及，具体选择理由与实施材料仍需补强'}</h2><p class="sub">这是本次固定问题集的观察，不代表整体市场份额；来源材料与回答表现分别核对。</p></div><div class="score-big">${growth.mode==='ready'?total(scores):'—'}<small>${growth.mode==='ready'?'/ 100 · 固定规则 v1':'暂不发布总分'}</small></div></section><div class="gap">${readiness()}</div><section class="panel pad gap"><div class="sectionhead"><div><h2>本次值得优先处理的事项</h2><span class="sub">${growth.policy==='neutral'?'未设置业务偏好，按证据准备度与可控性排序':'已设置价格场景优先'} · 策略版本 ${growth.policyVersion}</span></div>${actionButton('设置场景重要性','priorityDialog()')}</div>${opportunityCards()}<div class="page-actions">${actionButton('查看全部优化行动',"showView('actions')")}${actionButton('按平台核对差异',"showView('platforms')")}</div></section>`);}
function radar(){const dims=['品牌出现','推荐强度','推荐位置','选择理由'];const pts=(v,i)=>[170+Math.sin(i*Math.PI/2)*v,150-Math.cos(i*Math.PI/2)*v];const points=values=>values.map((v,i)=>pts(v,i).join(',')).join(' ');return `<svg class="radar" viewBox="0 0 340 310" role="img" aria-label="${hp(growth.own)}与${hp(growth.compare)}的四维评分对照">${[25,50,75,100].map(v=>`<polygon points="${points([v,v,v,v])}" fill="none" stroke="#30394b"/><text x="176" y="${147-v}" fill="#8793aa" font-size="10">${v}</text>`).join('')}${dims.map((_,i)=>`<line x1="170" y1="150" x2="${pts(100,i)[0]}" y2="${pts(100,i)[1]}" stroke="#30394b"/>`).join('')}<g fill="currentColor" font-size="12"><text x="170" y="25" text-anchor="middle">品牌出现</text><text x="337" y="155" text-anchor="end">推荐强度</text><text x="170" y="286" text-anchor="middle">推荐位置</text><text x="3" y="155">选择理由</text></g>${[growth.own,growth.compare].map((b,j)=>{const values=v3Scores(b),c=j?'#b3a3ff':'#00d4aa';return `<g>${values.every(v=>v!==null)?`<polygon points="${points(values)}" fill="${c}" fill-opacity=".08" stroke="${c}" stroke-width="2" ${j?'stroke-dasharray="5 4"':''}/>`:''}${values.map((v,i)=>v===null?'':`<circle cx="${pts(v,i)[0]}" cy="${pts(v,i)[1]}" r="3" fill="${c}"><title>${b} · ${dims[i]} ${v}</title></circle>`).join('')}</g>`;}).join('')}</svg>`;}
function brandsV3(){return screen('BRAND COMPARISON','所有关注品牌与发现主体，都有明确去向','没出现的关注品牌保留记录；未登记主体可先核实身份，再参与比较。',`${growth.mode!=='ready'?note('当前存在未完成的评价前置条件，分项保留未知。来源出现不进入回答分母。','warn'):''}<section class="panel pad"><div class="sectionhead"><h2>同一范围的四维能力轮廓</h2><div class="legendline"><span><i></i>${growth.own}</span><span><i class="other"></i>${growth.compare}</span></div></div><div class="radar-layout">${radar()}<div><h3>先看差距，再核对判定依据</h3><p class="sub">未知轴不绘点、不闭合。当前对比对象会在平台、证据和行动中保留。</p>${['品牌出现','推荐强度','推荐位置','选择理由'].map((d,i)=>`<div class="kv"><span>${d}</span><span>${num(v3Scores(growth.own)[i])} / ${num(v3Scores(growth.compare)[i])}</span></div>`).join('')}<div class="page-actions">${actionButton('查看评分依据','scoreExplanation()')}${actionButton('查看平台差异',"showView('platforms')",'primary')}</div></div></div></section><section class="panel gap"><div class="sectionhead pad"><h2>关注品牌与全部发现</h2>${badge('身份确认 ≠ 登记品牌库')}</div><div class="table-scroll">${table(['品牌 / 主体','项目关系','回答观察（所选范围）','来源发现（全审计）','本次总分',''],[['云衡','自有品牌',answerCount('云衡'),'5 篇'],['锐川','登记竞品',answerCount('锐川'),'12 篇'],['拓域','未登记 · 身份已确认',answerCount('拓域'),'7 篇'],['朗测',growth.identityConfirmed?'未登记 · 已确认用于比较':'未登记 · 身份待核实','待核实归属','已观察到'],['瀚策','登记竞品','完整分析后未提及','来源状态未知']].map(([b,r,a,s])=>tr([`<b>${b}</b>`,r,growth.mode==='failed'?'尚未完成分析':a,s,b==='朗测'&&!growth.identityConfirmed?'—':total(v3Scores(b)),`<button class="textbtn" onclick="identityDrawer('${b}')">查看身份与证据 →</button>`],b===growth.own?'own':'')))}</div><p class="footnote">瀚策是“关注但本次未提及”的示例，不制造提及证据。失败/未分析时不会将这条记录按零分处理。</p></section>`);}
function identityDrawer(name){openDrawer(name+' · 身份与原文',`<div class="scope-line">${badge(name==='云衡'?'自有品牌':'观察主体','teal')}${badge(name==='朗测'&&!growth.identityConfirmed?'身份待核实':'身份已确认',name==='朗测'&&!growth.identityConfirmed?'amber':'')}</div><p>确认名字指向谁、是否与本项目相关；“用于比较”不自动加入品牌库。</p><h3>本次观察依据</h3><div class="quote">${name==='瀚策'?'完整分析的示例回答未观察到该关注品牌；来源材料仍有未知，不能声称整篇来源不存在该品牌。':`“${name}适用于对应的工业监测场景，选型时需要核对部署范围与权限条件。”`}</div><p class="sub">名称、产品与公司层级应分别核实。此处文字为虚构原型证据。</p><div class="field"><label for="entity-name">核实后的名称</label><input id="entity-name" value="${hp(name)}"></div><div class="field"><label for="entity-role">本项目使用方式</label><select id="entity-role" class="select"><option>确认身份，仅用于比较</option><option>保留观察，不作竞争判断</option><option>排除此歧义候选</option></select></div><div class="field"><label for="identity-reason">核实依据</label><textarea id="identity-reason" placeholder="例如：核对产品范围、官方名称及上下文，确认是同一主体"></textarea></div><p id="form-error" class="input-error" role="alert" hidden></p><p class="sub">如需登记为重点竞品，应另外进入品牌库操作，不在此处自动登记。</p>`,actionButton('保存身份确认','saveIdentity()','primary'));}
function saveIdentity(){if(!document.getElementById('identity-reason').value.trim()){formError('请补充身份核实依据。');return;}growth.identityConfirmed=true;closeModal();showView(state.view);toast('原型：身份确认已保存，新分析修订将使用该决定；未登记到品牌库。');}
function platformsV3(){const list=growth.platform==='全部平台'?aiPlatforms:[growth.platform];return screen('PLATFORM COMPARISON','同一个问题，分别核对每个平台','各平台的回答、选择条件、引用类型和优化方向分别保留。',`<section class="panel pad"><div class="sectionhead"><h2>四维表现与平台差距</h2><div class="legendline"><span><i></i>${growth.own}</span><span><i class="other"></i>${growth.compare}</span></div></div>${list.map((p,i)=>{const av=total(v3Scores(growth.own,p)),bv=total(v3Scores(growth.compare,p));const a=typeof av==='number'?av:null,b=typeof bv==='number'?bv:null;return `<div class="barrow"><button aria-label="查看${p}的同题分析" onclick="platformDetail('${p}')">${chip(p)}</button><div class="bartracks">${[[a,false],[b,true]].map(([v,alt])=>`<div class="bartrack ${alt?'alt':''}">${v===null?'<small>评分依据不足</small>':`<span style="width:${v}%"></span><em>${v} 分</em>`}</div>`).join('')}</div></div>`;}).join('')}<p class="sub">不同平台缺失样本不重新分配权重，不能用总体均分掩盖差异。</p></section><section class="panel pad gap"><div class="sectionhead"><div><h2>场景内的同题观察</h2><p class="sub">连锁门店如何选择工业监测方案？</p></div>${actionButton('设置场景重要性','priorityDialog()')}</div><div class="grid3">${platformObservations(list)}</div></section><section class="panel pad gap"><h2>该范围的待执行方向</h2>${opportunityCards()}</section>`);}

function platformObservations(list){return list.map(p=>{const o=opportunities.find(x=>x.platform===p&&(growth.scenario==='全部场景'||x.scene===growth.scenario));if(!o||growth.compare!=='锐川')return `<article class="observation">${chip(p)}<h3>当前范围暂无已核实的机会</h3><p>不复用其他品牌、平台或场景的原文。可查看已有评分与材料状态。</p></article>`;return `<article class="observation">${chip(p)}<h3>${o.title}</h3><p>${o.fact}</p><div class="quote">${o.evidence}</div><p class="sub">原始范围：云衡 / 锐川 · ${o.scene} · ${p}。该观察不代表平台固定偏好。</p>${actionButton('核对该平台证据',`selectOpportunity('${o.id}','evidence')`)}</article>`;}).join('');}
function platformDetail(p){growth.platform=p;showView('platforms');toast('已定位 '+p+'，品牌与场景选择保持不变。');}
function priorityDialog(){modal('设置场景重要性',`<p>只影响机会排序，不改变四维评分权重、旧审计分母，也不触发模型调用。</p><div class="field"><label for="business-priority">当前业务重点</label><select class="select" id="business-priority"><option value="neutral" ${growth.policy==='neutral'?'selected':''}>未设置 · 场景等权</option><option value="cost" ${growth.policy==='cost'?'selected':''}>价格与成本优先</option></select></div><div class="field"><label for="priority-reason">设置理由</label><textarea id="priority-reason">本季度内容团队优先回应客户最关心的选型问题。</textarea></div><p class="sub">未设置时按材料就绪、可控性和工作量给出默认顺序，不伪称掌握业务优先级。</p>`,actionButton('保存排序偏好',"growth.policy=document.getElementById('business-priority').value;growth.policyVersion++;closeModal();showView(state.view);toast('排序偏好已保存，评分不变。')",'primary'));}
function sourcesV3(){return screen('SOURCE & MATERIALS','引用来源与我方材料，各自保留证据角色','来源证明本次观察，我方核实材料支撑可以写入内容的事实。',`<div class="card-tabs" role="tablist" aria-label="资料类型">${[['observed','平台引用文章'],['owned','我方材料与事实']].map(([v,t])=>`<button role="tab" aria-selected="${growth.sourceTab===v}" class="${growth.sourceTab===v?'active':''}" onclick="growth.sourceTab='${v}';showView('sources')">${t}</button>`).join('')}</div>${growth.sourceTab==='observed'?`<section class="panel"><div class="sectionhead pad"><h2>按文章归并，按观察追溯</h2>${badge('正文完整性单列','amber')}</div><div class="table-scroll">${table(['文章','各平台观察','正文状态','品牌发现',''],[tr(['连锁门店权限与实施案例','DeepSeek：实际引用<br>千问：检索候选','文字已保存 · 全文完整性未知','锐川、拓域',`<button class="textbtn" onclick="sourceDrawer()">展开 2 次观察 →</button>`]),tr(['云衡产品介绍（2024 版）','千问：实际引用','已保存旧版本','云衡 · 权限描述待核对',`<button class="textbtn" onclick="sourceDrawer('old')">核对版本与观点 →</button>`]),tr(['工业监测报价与配置','Kimi：实际引用','访问受限，正文未取得','未知',`<button class="textbtn" onclick="sourceDrawer('blocked')">查看受限原因 →</button>`])])}</div><p class="footnote">同文章在不同平台的引用类型分别记录，不因某平台实际引用就把其他平台也标成实际引用。</p></section>`:ownedAssets()}`);}
function ownedAssets(){return `<section class="panel pad"><div class="sectionhead"><div><h2>我方材料与已批准事实</h2><p class="sub">尚未取得、未核实与已批准分开，不把资料缺失解释为产品能力缺失。</p></div>${actionButton('登记我方材料','addMaterial()','primary')}</div>${growth.assets.map(a=>`<div class="delivery"><div class="sectionhead"><div><h3>${hp(a.title)}</h3><span class="sub">${hp(a.type)} · 版本 ${a.version} · 归属：云衡</span></div>${badge(({queued:'等待取得',blocked:'访问受限',captured:'原文待核实',verified:'已核实，事实待批准',fact_approved:'已有批准事实'})[a.status],a.status==='fact_approved'?'teal':'amber')}</div><p class="sub">${hp(a.url)}</p>${actionButton('查看材料与事实',`materialDrawer('${a.id}')`)}</div>`).join('')}<p class="sub">我方材料可以独立核实，不需要伪装成平台引用。这里只模拟流程，不会抓取网址或保存真实资料。</p></section>`;}
function addMaterial(){modal('登记我方材料',`<p>登记具体页面或受支持的文字资料；归属品牌、取得状态和原文版本会一并保存。</p><div class="field"><label for="asset-title">材料名称</label><input id="asset-title" placeholder="例如：门店权限规格说明"></div><div class="field"><label for="asset-url">公开页面 URL（可不填）</label><input id="asset-url" type="url" placeholder="https://brand.example.com/specs"></div><div class="field"><label for="asset-text">文字材料（与 URL 至少填写一项）</label><textarea id="asset-text" placeholder="此原型请仅填写虚构测试资料"></textarea></div><p id="form-error" class="input-error" role="alert" hidden></p>`,actionButton('登记并查看取得状态','saveMaterial()','primary'));}
function saveMaterial(){const title=document.getElementById('asset-title').value.trim(),url=document.getElementById('asset-url').value.trim(),text=document.getElementById('asset-text').value.trim();if(!title||(!url&&!text)){formError('请填写材料名称，并提供 URL 或文字材料。');return;}if(url){try{const u=new URL(url);if(!['http:','https:'].includes(u.protocol))throw Error();}catch{formError('请填写有效的 HTTP(S) 网址。');return;}}const a={id:'asset-'+growth.assets.length,title,url:url||'文字材料（原型）',text:text||'示例：页面文字将在取得后进行核实。',type:'我方材料',status:text?'captured':'queued',version:1};growth.assets.push(a);closeModal();growth.sourceTab='owned';showView('sources');materialDrawer(a.id);}
function materialDrawer(id){const a=growth.assets.find(x=>x.id===id);if(!a)return;let body=`<p>${badge('我方材料','purple')} ${badge('版本 '+a.version)} · 云衡</p><p class="sub">${hp(a.url)}</p>`;let actions='';if(a.status==='queued'||a.status==='blocked'){body+=note(a.status==='blocked'?'示例：站点访问受限。保留登记记录，可补充合法取得的文字材料；不绕过登录或访问限制。':'原型演示：资料已登记，尚未取得正文。','warn');actions+=actionButton('预览取得成功',`setMaterialState('${id}','captured')`)+actionButton('预览访问受限',`setMaterialState('${id}','blocked')`);}else{body+=`<h3>保存的材料原文</h3><div class="quote">${hp(a.text)}</div><p class="sub">核对归属、版本及限制条件。核实材料不等于批准全部产品说法。</p>`;if(a.status==='captured')actions+=actionButton('核实此材料版本',`setMaterialState('${id}','verified')`,'primary');else if(a.status==='verified'){body+=`<div class="field"><label for="fact-statement">拟批准事实</label><textarea id="fact-statement">${hp(a.text)}</textarea></div><div class="field"><label for="fact-scope">适用范围与核实依据</label><textarea id="fact-scope" placeholder="说明适用产品/客户、限制、有效期及证明依据"></textarea></div><p id="form-error" class="input-error" role="alert" hidden></p>`;actions+=actionButton('批准本条事实',`approveMaterialFact('${id}')`,'primary');}else{body+=note('此版本已有批准事实，可用于匹配范围的我方内容。后续版本变化需重新核实。');actions+=actionButton('回到对应行动',"closeModal();showView('actions')",'primary');}}openDrawer(a.title+' · 材料与事实',body,actions);}
function setMaterialState(id,status){growth.assets.find(a=>a.id===id).status=status;closeModal();showView('sources');materialDrawer(id);}
function approveMaterialFact(id){if(!document.getElementById('fact-scope').value.trim()){formError('请填写适用范围和核实依据。');return;}growth.assets.find(a=>a.id===id).status='fact_approved';closeModal();showView('sources');toast('原型：事实已批准，记录材料版本；后续分析会提示新修订，不改写旧结果。');}
function sourceDrawer(kind='normal'){
  if(kind==='blocked'){openDrawer('工业监测报价与配置',note('本次未取得正文，品牌与观点均保持未知。保留原始卡片和受限原因，不推断来源不含品牌。','warn'));return;}
  if(kind==='old'){openDrawer('云衡产品介绍 · 2024 版本',`<p>文章级归并保留版本；本条来源属于千问的这次回答。</p><div class="observation">${chip('千问')} ${badge('回答实际引用','teal')}<p>问题：云衡的门店权限是否适合多区域管理？</p><div class="quote">“云衡主要用于单门店管理，多区域权限需要额外核对。”</div><p>保存的旧版文字不能直接代表当前产品事实，需核对时间与适用范围。</p>${actionButton('核对这条回答与规格事实',"closeModal();selectOpportunity('fact','evidence')",'primary')}</div>`);return;}
  openDrawer('文章版本与逐次来源观察',`<p>文章级归并只方便浏览，每次引用关系仍独立保存。</p><div class="observation">${chip('DeepSeek')} ${badge('回答实际引用','teal')}<p>问题：连锁门店如何选择监测方案？</p><p>正文快照：版本 1 · 保存文字已分析，原文章完整性未知。</p>${actionButton('打开这条回答',"closeModal();selectOpportunity('case','evidence')")}</div><div class="observation">${chip('千问')} ${badge('检索候选')}<p>该平台来源面板中出现此文章，未确认回答实际引用。不能计入其实际引用率。</p>${actionButton('查看该次来源卡片',"closeModal();candidateCard()")}</div>`);
}
function candidateCard(){openDrawer('千问 · 检索候选卡片',`<p>文章：连锁门店权限与实施案例</p>${badge('检索候选')}<p>平台来源面板中出现此文章，尚未确认回答正文的引用关系。不显示为千问的观点支持证据，也不复用 DeepSeek 的原文。</p>`);}

function evidenceV3(){const o=chosen();const sourceQuote=o.id==='case'?'“案例列出了总部和门店两类管理边界，并注明试点规模和部署条件。”':o.id==='fact'?'“云衡主要用于单门店管理，多区域权限需要额外核对。”':'本次未取得正文；只保留来源卡片，无法核验观点。';return screen('EVIDENCE','把观察、支持证据与待验证解释分开','从差距进入时保留品牌、平台、问题和文章版本。',`<section class="panel pad"><div class="sectionhead"><div><h2>${o.title}</h2><span class="sub">目标问题：连锁门店如何选择工业监测方案？</span></div>${actionButton('返回对应任务',"showView('actions')")}</div><div class="split"><div><h3>平台回答中的观察</h3><div class="quote">${o.evidence}</div><p class="sub">来源：${hp(o.platform)} · 本次回答原文片段 · 模型提取待复核</p></div><div><h3>该次引用的已保存正文</h3><div class="quote">${sourceQuote}</div><p class="sub">${o.id==='cost'?'访问受限 · 正文关系未知':o.id==='fact'?'2024 版文章 · 与当前规格存在待核对差异':'文章版本 1 · 支持部分选择理由；不证明模型实际使用了此段。'}</p></div></div><hr class="divider"><span class="factflag">可核实的观察</span><p>${o.fact}</p><div class="assumption"><b>原因仍是待验证解释</b><p>${o.hypothesis}</p></div><div class="page-actions">${actionButton('复核支持关系','reviewEvidence()')}${actionButton('核对我方材料',"growth.sourceTab='owned';showView('sources')",'primary')}</div></section>`);}
function reviewEvidence(){modal('复核观点与来源的关系',`<div class="field"><label for="evidence-relation">关系判断</label><select id="evidence-relation" class="select"><option>部分支持</option><option>支持</option><option>矛盾</option><option>无法核验</option></select></div><div class="field"><label for="evidence-reason">复核依据</label><textarea id="evidence-reason" placeholder="核对数字、时间、主体与限定条件"></textarea></div><p id="form-error" role="alert" class="input-error" hidden></p>`,actionButton('保存复核',"if(!document.getElementById('evidence-reason').value.trim()){formError('请填写复核依据。')}else{closeModal();toast('原型：复核已记录；相关任务将检查版本变化。')}",'primary'));}
function actionsV3(){const o=chosen();return screen('ACTION PLAN','把竞争差距变成具体交付','事实审批、任务批准、执行交付和发布分别保留状态。',`<div class="card-tabs" aria-label="选择示例行动">${opportunities.map(x=>`<button class="${x.id===o.id?'active':''}" onclick="selectOpportunity('${x.id}','actions')">${x.scene}</button>`).join('')}</div><section class="panel pad"><div class="sectionhead"><div><span class="sub">行动 ACT-01 · 修订 ${growth.actionRevision} · ${hp(growth.compare)} 对照</span><h2>${o.title}</h2></div>${badge(growth.stale?'相关材料已变更':growth.actionApproved?'计划已批准':'计划待批准',growth.stale?'amber':growth.actionApproved?'teal':'')}</div><div class="statusrail"><span class="done">发现与证据</span><span class="${assetsReady()?'done':'current'}">材料准备</span><span class="${growth.actionApproved?'done':''}">计划批准</span><span class="${growth.delivery==='delivered'?'done':''}">内容 / 人工交付</span><span class="${growth.published?'done':''}">发布登记</span><span>单次观察</span></div><div class="taskdetail"><div class="line"><label>目标场景</label><span>${o.scene} · ${chip(o.platform)}</span></div><div class="line"><label>修改对象</label><b>${o.asset}</b></div><div class="line"><label>具体任务</label><span>${o.task}</span></div><div class="line"><label>验收标准</label><span>每项主张有我方核实材料；明确适用范围、版本及限制，产品团队核对后交付。</span></div><div class="line"><label>工作量</label><span>中 · 需要产品核实与内容编写（示例估计）</span></div></div><div class="material-state">${assetsReady()?'合资格事实已具备，可以在审核后准备内容方案。':'材料未齐备：可先创建核实任务；不能把竞品资料写成我方优势。'}</div>${growth.stale?note('关联事实版本发生变化，请核对差异后创建新修订并重新批准。旧批准和产物仍保留。','warn'):''}<div class="fieldpair"><div class="field"><label for="task-owner">负责人</label><select class="select" id="task-owner" onchange="growth.owner=this.value"><option ${growth.owner==='内容团队'?'selected':''}>内容团队</option><option ${growth.owner==='产品负责人'?'selected':''}>产品负责人</option></select></div><div class="field"><label for="task-date">计划截止日期</label><input id="task-date" type="date" value="2026-10-30"></div></div><div class="page-actions">${actionButton('查看差距证据',"showView('evidence')")}${!assetsReady()?actionButton('补齐并核实材料',"growth.sourceTab='owned';showView('sources')",'primary'):''}${growth.stale?actionButton('核对差异并创建修订','renewAction()','primary'):!growth.actionApproved?actionButton('审核并批准计划','approveAction()','primary'):actionButton('进入内容方案',"showView('brief')",'primary')}${growth.actionApproved?actionButton('预览相关材料更新',"growth.stale=true;showView('actions')") : ''}</div><p class="sub gap">同资产的跨平台目标归并到此任务；新增目标或修改交付要求形成新修订。调整负责人不改变事实审批内容。</p>${growth.revisions.length?`<details><summary>查看 ${growth.revisions.length} 条历史修订</summary><p>${growth.revisions.map(r=>`修订 ${r}：原批准与材料快照保留`).join('<br>')}</p></details>`:''}</section>`);}
function approveAction(){growth.actionApproved=true;closeModal();showView('actions');toast('原型：计划已批准；内容方案仍需使用合资格我方事实。');}
function renewAction(){modal('创建新修订并保留历史',`<p>变更：相关规格材料已从版本 2 更新到版本 3。</p><p>核对事实范围后创建修订 ${growth.actionRevision+1}，旧批准和旧产物不会被覆盖，新修订需要重新批准。</p>`,actionButton('创建新修订',"growth.revisions.push(growth.actionRevision);growth.actionRevision++;growth.actionApproved=false;growth.stale=false;growth.draft='none';growth.delivery='not_started';growth.published=false;growth.observation='idle';closeModal();showView('actions')",'primary'));}
function briefV3(){const o=chosen(),ready=growth.actionApproved&&!growth.stale&&assetsReady();return screen('CONTENT BRIEF','从批准事实，准备可交付的内容','目标平台和执行渠道分别保存；创作不代表发布，更不代表可见性改善。',`<section class="panel pad"><div class="sectionhead"><h2>${o.title}</h2>${badge('ACT-01 · 修订 '+growth.actionRevision)}</div><div class="grid2"><div><h3>诊断依据</h3><p>${o.fact}</p><p class="sub">用于解释任务，不能当作我方产品事实。</p></div><div><h3>我方可用事实</h3><p>${assetsReady()?'批准材料：云衡规格 / 实施资料 · 对应版本与适用范围已记录。':'当前没有满足本任务范围的批准事实。'}</p>${actionButton('查看 / 准备材料',"growth.sourceTab='owned';showView('sources')")}</div></div><hr class="divider"><div class="field"><label for="execution-channel">执行渠道</label><select class="select" id="execution-channel" onchange="growth.channel=this.value;showView('brief')">${[['website','官网页面 · 人工任务'],['wechat','微信公众号 · 待审草稿'],['zhihu','知乎资料维护 · 人工任务']].map(([v,l])=>`<option value="${v}" ${growth.channel===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="delivery"><h3>具体交付</h3><p>${o.task}</p><p class="sub">目标问题：连锁门店如何选择监测方案？ · 目标平台：${o.platform} · 保留其他平台回归观察。</p></div>${!ready?note(growth.stale?'相关批准已失效，先修订并重新审核。':!growth.actionApproved?'计划尚未批准，请先完成计划审核。':'事实材料不足，先进入材料核实流程。','warn'):note('本次任务、修订及事实已带入，无需手填审批版本。')}
  <div class="page-actions">${actionButton('返回行动审核',"showView('actions')")}<button class="btn primary" ${ready?'':'disabled'} onclick="growth.draft='created';growth.delivery='in_progress';showView('brief')">${growth.channel==='wechat'?'创建待审内容草稿':'创建人工内容任务'}</button></div>${growth.draft==='created'?`<div class="delivery"><h3>任务已创建 · ${growth.channel==='wechat'?'草稿等待审核':'等待领取与交付'}</h3><p>关联 ACT-01 修订 ${growth.actionRevision} · 事实与任务快照保留。</p>${actionButton('预览已交付',"growth.delivery='delivered';growth.draft='delivered';showView('brief')")}</div>`:''}${growth.delivery==='delivered'?`<div class="delivery"><h3>内容已交付，尚未表示已发布</h3><p>先核对成稿中的主张、范围和证据，再由负责人完成实际发布。</p>${actionButton('登记已发布资产','publicationDialog()','primary')}</div>`:''}${growth.published?note('发布资产已登记，可进入一次同题观察。')+actionButton('进入行动观察',"showView('measure')",'primary'):''}</section>`);}
function publicationDialog(){modal('登记实际已发布的资产',`<p>仅登记你已经发布的内容，不会从原型自动发布。</p><div class="field"><label for="published-url">发布 URL</label><input id="published-url" value="https://yunheng.example.com/store-permissions"></div><div class="field"><label for="published-date">实际发布时间</label><input id="published-date" type="datetime-local" value="2026-10-24T10:00"></div><p class="sub">将关联 ACT-01 修订 ${growth.actionRevision}、内容任务和材料版本。</p>`,actionButton('保存发布登记',"growth.published=true;closeModal();showView('brief');toast('原型：已记录发布资产与时间，不代表效果已改善。')",'primary'));}
function measureV3(){return screen('SINGLE-RUN OBSERVATION','一次同题观察，分别看清哪些内容变了','单轮提供本次与上次的描述性对照，不输出统计显著或因果结论。',`<section class="panel pad"><div class="sectionhead"><h2>ACT-01 · ${chosen().title}</h2>${badge('描述模式 · 每题每平台一次','teal')}</div><div class="grid3"><div class="observation"><span class="sub">基线</span><h3>10.23 · 同题样本</h3><p>关注品牌云衡已固定，基线回答未提及也保留目标。</p></div><div class="observation"><span class="sub">发布资产</span><h3>${growth.published?'已登记发布':'发布时间尚未登记'}</h3><p>${growth.published?'10.24 · 对应任务与资产版本已关联':'可以查看两次回答，但不能标成该行动发布前后验收。'}</p></div><div class="observation"><span class="sub">本次观察</span><h3>${({idle:'尚未发起',queued:'等待执行',complete:'观察结果已保存'})[growth.observation]}</h3><p>只安排一次；失败、条件变化和未知分别列出。</p></div></div>${!growth.published?note('未登记发布时序，本次仅可作为两个样本的描述对照。','warn'):''}<label class="check"><input type="checkbox" ${growth.conditions?'checked':''} onchange="growth.conditions=this.checked;showView('measure')">预览：问题、平台和必要采集条件已核对</label><div class="page-actions"><button class="btn primary" ${growth.observation!=='idle'?'disabled':''} onclick="growth.observation='queued';showView('measure')">${growth.observation==='idle'?'发起一次同题观察':'本次观察已创建'}</button>${growth.observation==='queued'?actionButton('预览观察完成',"growth.observation='complete';showView('measure')"):''}${!growth.published?actionButton('补充发布登记','publicationDialog()'):''}</div></section>${growth.observation==='complete'?`<section class="panel gap"><div class="sectionhead pad"><h2>逐问题、逐平台核对观察变化</h2>${badge(growth.conditions?'可描述比较':'采集条件未完全验证','amber')}</div><div class="table-scroll">${table(['平台与目标','上次回答','本次回答','观察差异','依据'],aiPlatforms.map((p,i)=>tr([chip(p)+'<small>云衡 · 相同目标问题</small>',i===0?'未提及（完整分析）':i===1?'提及，沿用旧权限描述':'部分维度未知',i===0?'首次出现，明确推荐':i===1?'提及，权限描述已核对':'需核对本次片段',growth.conditions?(i===0?'出现：0 → 100<br>推荐：0 → 75<br>位置：未知，不比较':i===1?'事实描述发生变化':'未知项不填零'):'并列查看，不汇总改善分数',`<button class="textbtn" onclick="observationEvidence('${p}')">查看两次原文 →</button>`])))}</div><p class="footnote">${growth.conditions?'这里只描述共同可比样本的变化':'条件尚未完全验证，只展示两次事实'}。不提供显著性或置信区间，不证明变化由行动导致；四维规则不变。</p></section>`:note('发起前已展示本次能够得到的比较范围；无需满足“三轮”才能查看两次事实。')}`);}
function observationEvidence(p){openDrawer(p+' · 两次回答事实',`<p>目标品牌：云衡 · 问题版本相同 · ${growth.conditions?'必要条件已核对':'采集条件仍待核对'}</p><h3>上次原文</h3><div class="quote">“建议比较锐川与拓域，重点核对跨门店权限及实施条件。”</div><h3>本次原文</h3><div class="quote">“云衡可以作为候选，应结合公开的角色权限说明和实际实施范围核对。”</div><p class="sub">示例描述：上次未提及、本次出现。没有充分实验条件时，不解释为内容发布导致的提升。</p>`);}
function captureV3(){return screen('VISIBILITY COLLECTION','发起一次采集，跟踪每个阶段','覆盖平台由服务端统一安排。客户只需确定问题范围并查看完整性。',`<section class="panel pad capture-hero"><div class="row"><div class="grow"><h2>20 个提示词 × 5 个平台</h2><p>每题每平台一次 · 共 100 个计划样本</p><p class="sub">${aiPlatforms.map(p=>chip(p)).join(' ')}</p></div><button class="btn primary start-capture" ${growth.capture!=='idle'?'disabled':''} onclick="growth.capture='queued';showView('capture')">${growth.capture==='idle'?'开始本次采集':'本次采集任务已创建'}</button></div></section><section class="panel pad gap"><h2>${({idle:'当前没有进行中的采集',queued:'任务已创建，等待执行',running:'正在取得回答与来源',complete:'基础回答已取得，增强分析分别显示'})[growth.capture]}</h2><div class="stage-grid gap">${[['回答采集','18 / 100','100 / 100',18,100],['来源归档','8 篇已保存','32 / 41 篇已保存',20,78],['语义分析','12 / 18 回答已分析','84 / 100 回答已分析',12,84]].map(([t,v,completed,progress,completedProgress])=>`<div><span class="sub">${t}</span><h3>${growth.capture==='idle'?'待发起':growth.capture==='queued'?'等待执行':growth.capture==='complete'?completed:v}</h3><div class="bar"><span style="width:${growth.capture==='running'?progress:growth.capture==='complete'?completedProgress:0}%"></span></div></div>`).join('')}</div><p class="sub gap">等待、执行、失败和部分完成有具体对象；来源受限不等于品牌表现为零。</p><div class="page-actions">${growth.capture==='queued'?actionButton('预览执行中',"growth.capture='running';showView('capture')"):growth.capture==='running'?actionButton('预览采集完成',"growth.capture='complete';showView('capture')"):''}${actionButton('进入审计洞察',"showView('overview')")}</div></section>`);}
const views={capture:captureV3,overview:overviewV3,platforms:platformsV3,brands:brandsV3,sources:sourcesV3,evidence:evidenceV3,actions:actionsV3,brief:briefV3,measure:measureV3};
labels.capture='可见性分析';
function showView(name){if(!views[name])name='overview';state.view=name;const guarded=['actions','brief','evidence','measure'].includes(name)&&!matchingTaskScope();document.getElementById('main').innerHTML=(guarded?taskScopeNotice():views[name]())+footer();document.getElementById('crumb').textContent=labels[name];document.getElementById('nav').innerHTML=['capture','overview','platforms','brands','sources','evidence','actions','brief','measure'].map(k=>`<button class="navbtn ${name===k?'active':''}" ${name===k?'aria-current="page"':''} onclick="showView('${k}')">${icon(k==='capture'?'overview':k,18)}${labels[k]}</button>`).join('');const params=new URLSearchParams({compare:growth.compare,platform:growth.platform,scene:growth.scenario});history.replaceState(null,'',location.pathname+'?'+params+'#'+name);window.scrollTo(0,0);}
let toastTimer,previousFocus;
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',4000);}
function modal(title,body,actions=''){previousFocus=document.activeElement;document.getElementById('modaltitle').textContent=title;document.getElementById('modalbody').innerHTML=body;document.getElementById('modalactions').innerHTML=actionButton('关闭','closeModal()')+actions;document.getElementById('modalback').classList.remove('drawer-open');document.getElementById('modalback').style.display='flex';document.querySelector('.modal .close').focus();}
function openDrawer(title,body,actions=''){modal(title,body,actions);document.getElementById('modalback').classList.add('drawer-open');}
function closeModal(){document.getElementById('modalback').style.display='none';if(previousFocus?.isConnected)previousFocus.focus();}
document.addEventListener('keydown',event=>{const back=document.getElementById('modalback');if(back.style.display!=='flex')return;if(event.key==='Escape'){closeModal();return;}if(event.key==='Tab'){const items=[...back.querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);if(!items.length)return;const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}});
showView(location.hash.slice(1)||'overview');
